import React from 'react';

import styles from './styles.module.less';

const FinanceReceiptHTML = ({ html }: { html: string }) => {
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!ref.current) return;
    const sanitizerConfig = {};
    const sanitizer = new Sanitizer(sanitizerConfig);
    const preparedHTML = html.replace('src="/', 'src="//proverkacheka.com/');

    if ('setHTML' in ref.current) {
      // eslint-disable-next-line @typescript-eslint/ban-ts-comment
      //@ts-ignore
      ref.current.setHTML(preparedHTML, { sanitizer });
    } else {
      // Fallback for browsers without the API yet
      ref.current.textContent = `<iframe
        src="data:text/html;charset=utf-8,${encodeURI(preparedHTML)}"}
        frameBorder="0"
      ></iframe>`;
    }
  }, [html]);

  return <div className={styles.check} ref={ref} />;
};

export default FinanceReceiptHTML;
