import { IProductUnitDTO } from '../@types/productUnits.backTypes';
import { IProductUnit } from '../@types/productUnits.types';

export const mapBackProductUnitToFront = (backData: IProductUnitDTO): IProductUnit => {
  return {
    id: +backData.id,
    name: backData.name,
    short_name: backData.short_name,
  };
};
